import { IAssetConfig } from '@game-studio/asset-manager';
import { gameConfig } from '../models/config-model';
import { inversifyContainer } from '../inversify/container';
import { IAdminSettings, IAssetVersion } from '../types';
import { container, Injects } from '../index';

export class BaseAdminSettings implements IAdminSettings {
    public static get Instance(): BaseAdminSettings { return this._instance || (this._instance = new BaseAdminSettings()); }
    protected static _instance: BaseAdminSettings;

    protected _assetVersion: IAssetVersion = { core: '', skin: '' };
    protected _errorStringsVersion: string = '';
    protected _sharedStringsVersion: string = '';
    protected _settingsStringsVersion: string = '';
    protected _recentWinnersName: string = '';

    public get assetVersion(): IAssetVersion { return this._assetVersion; }
    public get errorStrings(): string { return this._errorStringsVersion; }
    public get sharedStrings(): string { return this._sharedStringsVersion; }
    public get settingsStrings(): string { return this._settingsStringsVersion; }
    public get recentWinnersName(): string { return this._recentWinnersName; }

    protected constructor() { }

    public async initialise(): Promise<void> {
        const usingLocalAssets: boolean = gameConfig.features.usingLocalAssets;
        const legacyCoreVersion: string | undefined = gameConfig.legacyCoreVersion;
        const isUsingPOEditor: boolean = container.isBound(Injects.TranslationVersions);

        let coreAssetVersion: string = '';
        let skinAssetVersion: string = '';

        if (usingLocalAssets) {
            if (!isUsingPOEditor) {
                if (legacyCoreVersion === undefined) {
                    console.error('usingLocalAssets is set to true in the config.json but legacyCoreVersion is missing. \nIf you wish to use local assets, please provide the core asset version.');
                } else {
                    coreAssetVersion = legacyCoreVersion;
                }
            }
        } else {
            if (inversifyContainer.coreDataList.version === undefined) {
                console.error('Version inside of your asset list is Undefined. If using the local asset setup, please ensure you have set `usingLocalAssets` to true in your config.json');
                return;
            }

            coreAssetVersion = inversifyContainer.coreDataList.version;
            skinAssetVersion = (inversifyContainer.skin.dataList as IAssetConfig).version;
        }

        this._assetVersion.core = coreAssetVersion;
        this._assetVersion.skin = skinAssetVersion;

        this._errorStringsVersion = 'ver-3.4';
        this._sharedStringsVersion = 'ver-3.8';
        this._settingsStringsVersion = 'ver-1.0';

        this._recentWinnersName = gameConfig.recentWinnersName ?? gameConfig.gameCategory;
    }
}